PRAGMA foreign_keys = ON;

CREATE TABLE roadmap_milestones (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  target_version TEXT,
  objective TEXT NOT NULL,
  release_acceptance_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(release_acceptance_json)),
  status TEXT NOT NULL CHECK (status IN ('developing','planned')),
  position INTEGER NOT NULL UNIQUE
);
CREATE TABLE roadmap_categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  position INTEGER NOT NULL UNIQUE
);
CREATE TABLE roadmap_features (
  id TEXT PRIMARY KEY,
  category_id TEXT NOT NULL REFERENCES roadmap_categories(id),
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  milestone_id TEXT NOT NULL REFERENCES roadmap_milestones(id),
  is_required INTEGER NOT NULL CHECK (is_required IN (0,1)),
  acceptance_criteria_json TEXT NOT NULL CHECK (json_valid(acceptance_criteria_json)),
  upstream_references_json TEXT NOT NULL CHECK (json_valid(upstream_references_json)),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE roadmap_feature_status (
  feature_id TEXT NOT NULL REFERENCES roadmap_features(id) ON DELETE CASCADE,
  scenario TEXT NOT NULL DEFAULT 'actual' CHECK (scenario IN ('actual','demo')),
  state TEXT NOT NULL DEFAULT 'planned' CHECK (state IN ('planned','developing','testing','verified')),
  updated_by TEXT REFERENCES collaborators(id),
  updated_at INTEGER NOT NULL,
  change_reason TEXT NOT NULL DEFAULT '',
  last_change_id TEXT,
  verified_by TEXT REFERENCES collaborators(id),
  verified_at INTEGER,
  PRIMARY KEY (feature_id, scenario),
  CHECK ((state='verified' AND verified_by IS NOT NULL AND verified_at IS NOT NULL) OR (state!='verified' AND verified_by IS NULL AND verified_at IS NULL))
);
CREATE TABLE roadmap_feature_tasks (
  id TEXT NOT NULL UNIQUE,
  feature_id TEXT NOT NULL REFERENCES roadmap_features(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL REFERENCES tasks(id),
  scenario TEXT NOT NULL DEFAULT 'actual' CHECK (scenario IN ('actual','demo')),
  linked_by TEXT NOT NULL REFERENCES collaborators(id),
  linked_at INTEGER NOT NULL,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  updated_by TEXT REFERENCES collaborators(id),
  updated_at INTEGER,
  last_change_id TEXT,
  PRIMARY KEY (feature_id, task_id, scenario)
);
CREATE TABLE roadmap_feature_evidence (
  id TEXT PRIMARY KEY,
  feature_id TEXT NOT NULL REFERENCES roadmap_features(id) ON DELETE CASCADE,
  scenario TEXT NOT NULL DEFAULT 'actual' CHECK (scenario IN ('actual','demo')),
  url TEXT NOT NULL,
  label TEXT NOT NULL,
  description TEXT NOT NULL,
  is_valid INTEGER NOT NULL DEFAULT 1 CHECK (is_valid IN (0,1)),
  created_by TEXT NOT NULL REFERENCES collaborators(id),
  created_at INTEGER NOT NULL,
  invalidated_by TEXT REFERENCES collaborators(id),
  invalidated_at INTEGER,
  last_change_id TEXT
);
CREATE TABLE roadmap_change_history (
  id TEXT PRIMARY KEY,
  feature_id TEXT REFERENCES roadmap_features(id) ON DELETE SET NULL,
  actor_id TEXT REFERENCES collaborators(id),
  action TEXT NOT NULL,
  details_json TEXT NOT NULL CHECK (json_valid(details_json)),
  created_at INTEGER NOT NULL,
  scenario TEXT NOT NULL DEFAULT 'actual' CHECK (scenario IN ('actual','demo'))
);
CREATE TABLE roadmap_catalog_imports (
  catalog_hash TEXT PRIMARY KEY,
  catalog_version TEXT NOT NULL,
  source_revision TEXT NOT NULL,
  feature_count INTEGER NOT NULL,
  imported_by TEXT REFERENCES collaborators(id),
  imported_at INTEGER NOT NULL
);
CREATE INDEX roadmap_features_category_milestone ON roadmap_features(category_id,milestone_id,active,id);
CREATE INDEX roadmap_features_milestone ON roadmap_features(milestone_id,active,is_required);
CREATE INDEX roadmap_feature_status_state ON roadmap_feature_status(scenario,state,feature_id);
CREATE INDEX roadmap_feature_tasks_task ON roadmap_feature_tasks(task_id,scenario,active);
CREATE INDEX roadmap_feature_tasks_feature ON roadmap_feature_tasks(feature_id,scenario,active);
CREATE INDEX roadmap_feature_evidence_feature ON roadmap_feature_evidence(feature_id,scenario,is_valid,created_at DESC);
CREATE INDEX roadmap_history_recent ON roadmap_change_history(created_at DESC,id DESC);
CREATE INDEX roadmap_history_feature ON roadmap_change_history(feature_id,created_at DESC,id DESC);
CREATE INDEX roadmap_imports_recent ON roadmap_catalog_imports(imported_at DESC);



;
