INSERT INTO roadmap_milestones (id,name,target_version,objective,release_acceptance_json,status,position) VALUES
  ('foundation','Foundation',NULL,'Architecture, licensing, tests and foundations','[]','developing',1),
  ('prototype','Prototype','v0.1','Connection, world interpretation and movement','["Connect to a server.","Select a character.","Enter a map.","Identify actors.","Move.","Confirm arrival."]','planned',2),
  ('alpha','Alpha','v0.2','First usable combat and gathering release','["Connect.","Navigate within a map.","Select targets.","Fight.","Use skills.","Collect items.","Recover HP/SP.","Repeat the cycle autonomously."]','planned',3),
  ('beta','Beta','v0.5','Complete automation cycles','["Leave town.","Reach the lockMap.","Fight.","Collect items.","Return.","Store items.","Sell items.","Buy supplies.","Restart the cycle."]','planned',4),
  ('rc','Release Candidate','v0.9','Broad functional compatibility','["Validate the advanced systems defined in the feature catalogue.","Validate extensibility.","Validate compatibility.","Validate stability."]','planned',5),
  ('stable','Stable','v1.0','First stable release','["Validate all accumulated mandatory requirements.","Validate documentation.","Validate multiplatform distribution.","Validate regression results."]','planned',6);
